import networkx as nx

edges = [(0, 1), (0, 5), (1, 3), (2, 5), (2, 8), (3, 4), (4, 6), (6, 7), (7, 8)]
G = nx.Graph(edges)

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        for length, path in nx.single_source_shortest_path(G, n).items():
            for neighbor in G.neighbors(n):
                if neighbor in path and path.index(neighbor) > 1:
                    girth = min(girth, length + 1)
    return girth

print("Girth:", get_girth(G))
try:
    cycles = nx.cycle_basis(G)
    print("Cycle lengths:", [len(c) for c in cycles])
except:
    pass
